  'editor.pers.anim': 'Animacja',
  'editor.pers.animFlote': 'Ruch zastępuje naturalne unoszenie się postaci; machnięcie ręką zostaje zachowane.',
  'editor.pers.animSinPiezas': 'Aby tworzyć animacje z pozami, zbuduj ciało z elementów 3D w zakładce Ciało.',
  'room.cocina.desc': 'Odżywianie: zapisuj posiłki, makroskładniki, wodę i swój plan tygodniowy.',
  'room.ejercicio.desc': 'Rutyny siły, wytrzymałości i elastyczności z celami.',
  'room.recamara.desc': 'Śledź swój odpoczynek i prowadź osobisty dziennik wspomnień.',
  'room.descanso.desc': 'Twój sen jako nocne niebo: harmonogram, budzik, ocena i dziennik nocy.',
  'room.anecdotario.desc': 'Twój dziennik wspomnień: wspomnienia ze zdjęciami i codzienny nastrój.',
  'room.despacho.desc':
    'Finanse: budżet z wydatkami i przychodami (stałymi i zmiennymi), cele (kalkulatory finansowe, oszczędzanie/inwestowanie, zadłużenie) z symulatorami oraz rynki na żywo.',
  'room.biblioteca.desc': 'Encyklopedia konwersacyjna: rozmowy z AI, wpisy wiki i sesje nauki.',
  'room.entretenimiento.desc': 'Archiwum filmów, seriali, książek i gier planszowych.',
  'room.sala.desc': 'Planuj podróże: trasa, wydatki, lista kontrolna i lista życzeń.',
  'room.jardin.desc': 'Spokój: medytacje prowadzone, oddychanie i dziennik wdzięczności.',
  'room.garage.desc': 'Konserwacja twoich pojazdów i ich serwisów.',
  'room.diario.desc': 'Centrum codziennych wiadomości według kategorii.',
  'room.hobbies.desc': 'Twoje hobby i projekty twórcze.',
  'room.idiomas.desc':
    'Ucz się języków: nauczyciel AI, słownictwo z powtórkami rozłożonymi w czasie, program poziomów i ćwiczenia.',
  'room.calendario.desc': 'Twój kalendarz: wydarzenia i rutyny według dnia, tygodnia i miesiąca.',
  'room.caminos.desc': 'Wytycz tory wyścigowe, szyny kolejowe i kolejki górskie na mapie.',
  'room.canchas.desc': 'Umieść na mapie boiska do piłki nożnej, tenisa, koszykówki i baseballu.',
  'room.huerto.desc': 'Przygotuj grządki, sadź uprawy, podlewaj je i zbieraj plony w czasie rzeczywistym.',
  'room.granja.desc': 'Hoduj kury, świnie, kozy, owce, krowy i konie oraz uprawiaj ich paszę w tym samym edytorze.',
  'room.ideas.desc':
    'Twój dziennik pomysłów i burz mózgów, dziesięć formatów map myśli na dowolnym płótnie (mapa myśli, drzewo, oś czasu, cykl, piramida, diagram Venna…) i osiem diagramów decyzyjnych (za i przeciw, pole sił, SWOT, macierz Eisenhowera, drzewo decyzyjne, tier list, ważona macierz decyzyjna i Ishikawa), ręcznie lub z AI.',
  'room.metas.desc':
    'Twoje postanowienia z całego domu: lista celów z ich podcelami i krokami, plany, które AI proponuje dla każdego z nich (etapy z datą, które stają się prawdziwymi podcelami), oraz harmonogram, gdzie wszystko zajmuje swój okres na osi czasu.',
  'room.computo.desc':
    'Sala komputerowa: kalkulator naukowy z Twoim zbiorem wzorów (Matematyka, Fizyka i Chemia gotowe do edycji) i ośmioma trybami — wykreślacz z czterema typami (2D, biegunowy, parametryczny i powierzchnia 3D), dwójkowy i szesnastkowy, macierze, układy równań, przeliczanie jednostek, napiwek i reguła trzech; oraz arkusze, które eksportują się do Excela i PDF.',
