  'mascota.mago.saludo': 'Jestem twoim tajemnym architektem. Powiedz mi, co zrobiono, a ja to zapiszę ✨',
  'mascota.gato.saludo': 'Miau. Powiedz, o co chodzi, a zobaczę, gdzie to wsadzić 🐾',
  'mascota.perro.saludo': 'Hau! Opowiedz, co zrobiono, a zaraz to zapiszę! 🦴',
  'mascota.buho.saludo': 'Mądra i uważna. Zdaj relację ze swojego dnia, a ja go uporządkuję.',
