  'mascota.gato.sinClasificar.1': 'Pfff, do którego pokoju to należy? Ty mi powiedz.',
  'mascota.gato.agregar.0': 'Dobra, postawiłem {c} na mapie. I tak się nudziłem 🐱',
  'mascota.gato.agregar.1': 'Dodałem {c}. Gratulacje, chyba.',
